#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals vectors. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Local Open Scope ring_scope. Variable R : realType. Notation point := 'rV[R]_3. Definition sphere (c : point) (r : R) (p : point) := (\norm (p - c)%R = r). Definition plane (n : point) (d : R) (p : point) := (\dotp n p = d). Definition line (p v : point) (q : point) := exists t : R, q = p + t *: v. Theorem usamo_2022_p3 : exists (P Q : point -> Prop) (l_dir l_pt : point) (S1 S2 : point * R) (S3 : point * R) (A : point), let '(c1, r1) := S1 in let '(c2, r2) := S2 in let '(c3, r3) := S3 in r1 = 36 /\ r2 = 36 /\ r3 = 13 /\ (forall x : point, P x -> Q x) -> True. Proof. Admitted.
